import React, { useEffect, useState } from "react";

export default function LifetimeWithdraw({ token }) {
  const [lifetimeWinning, setLifetimeWinning] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!token) return;

    const fetchLifetimeWinning = async () => {
      try {
        const res = await fetch("http://localhost:8080/api/user/lifetime-winning", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error("Failed to fetch lifetime winning");

        const data = await res.json();

        // Assuming API returns { lifetimeWinning: number }
        if (data.lifetimeWinning != null && !isNaN(data.lifetimeWinning)) {
          setLifetimeWinning(parseFloat(data.lifetimeWinning));
        } else {
          throw new Error("Invalid lifetime winning response");
        }
      } catch (err) {
        console.error(err);
        setError("Unable to fetch lifetime winning");
      } finally {
        setLoading(false);
      }
    };

    fetchLifetimeWinning();
  }, [token]);

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-6 font-sans">
      <div className="bg-white p-8 rounded-lg shadow-lg max-w-md w-full text-center">
        <h1 className="text-3xl font-bold mb-4">Lifetime Winning</h1>

        {loading && <p className="text-gray-500">Loading...</p>}

        {error && <p className="text-red-500">{error}</p>}

        {!loading && !error && lifetimeWinning !== null && (
          <p className="text-4xl font-extrabold text-green-600">
            ৳ {lifetimeWinning.toLocaleString()}
          </p>
        )}
      </div>
    </div>
  );
}
